import { NullLogService } from '../../out/vs/platform/log/common/log.js';

test('real Agent Host bridge + SDK + native runtime: fixture catalog, model switch, resume, inference, and revocation', { timeout: 120_000 }, async t => {
	const requests = [];
	const responseText = 'native SDK fixture works';
	const server = createServer(async (request, response) => {
		let text = '';
		for await (const bytes of request) {
			text += bytes.toString();
		}
		requests.push({ method: request.method, path: request.url, headers: request.headers, model: text ? JSON.parse(text).model : undefined });
		if (request.method === 'GET' && request.url === '/llmapi/models') {
			response.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({
				data: ['gpt-5-mini', 'gpt-5-nano'].map(id => ({ id, supported_endpoints: ['/chat/completions'] })),
			}));
		} else if (request.method === 'POST' && request.url === '/llmapi/chat/completions') {
			response.writeHead(200, { 'Content-Type': 'text/event-stream' }).end(
				`data: ${JSON.stringify({
					id: 'fixture', object: 'chat.completion.chunk', model: JSON.parse(text).model,
					choices: [{ index: 0, delta: { role: 'assistant', content: responseText }, finish_reason: 'stop' }],
					usage: { prompt_tokens: 1, completion_tokens: 1, total_tokens: 2 },
				})}\n\ndata: [DONE]\n\n`,
			);
		} else {
			response.writeHead(500).end('Unexpected fixture request');
		}
	});
	await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
	let home;
	let bridge;
	let client;
	t.after(async () => {
		try {
			await client?.stop();
		} finally {
			bridge?.dispose();
			server.closeAllConnections();
			await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
			if (home) {
				await rm(home, { recursive: true, force: true });
			}
		}
	});
	home = await mkdtemp(join(tmpdir(), 'agenthost-loki-sdk-fixture-'));
	const token = 'fake-host-owned-agenthost-fixture-token';
	const initial = { resource: NATIVE_LOKI_PROTECTED_RESOURCE.resource, scopes: [NATIVE_LOKI_SCOPE], token, _meta: nativeLokiAuthenticationMeta({ accountId: 'fixture-account' }) };
	let renewalCount = 0;
	bridge = new CopilotNativeLoki(resolve(process.env.VSCODE_NATIVE_LOKI_RUNTIME_ROOT ?? '.build/copilot-runtime-pr-22745/dist-cli'), undefined, resource => {
		renewalCount++;
		bridge.acceptToken({ ...initial, _meta: resource._meta });
	}, new NullLogService());
	bridge.acceptToken(initial);
	client = new CopilotClient({
		...bridge.clientOptions,
		connection: RuntimeConnection.forStdio({ path: await bridge.resolveRuntimePath() }),
		useLoggedInUser: false,
		env: {
			PATH: process.env.PATH, HOME: home, COPILOT_HOME: home, TMPDIR: process.env.TMPDIR,
			COPILOT_DISABLE_KEYTAR: '1', COPILOT_CLI_TELEMETRY_OPTOUT: '1',
			COPILOT_LOKI_BASE_URL: `http://127.0.0.1:${server.address().port}/llmapi`,
		},
	});
	await client.start();
	const models = await bridge.listModels(client);
	assert.deepStrictEqual(models.map(model => ({ id: model.id, provider: model.modelProviderId === 'loki:fixture-account' ? 'loki' : model.modelProviderId })), [
		{ id: 'gpt-5-mini', provider: 'loki' }, { id: 'gpt-5-nano', provider: 'loki' },
	]);
	const sessionOptions = {
		availableTools: [], enableConfigDiscovery: false, infiniteSessions: { enabled: false }, streaming: true,
		onPermissionRequest: () => ({ kind: 'denied-interactively-by-user' }),
	};
	let session = await client.createSession(sessionOptions);
	await assert.rejects(bridge.prepareSession(session, 'not-a-native-model'), /not in the native Loki catalog/);
	await bridge.prepareSession(session, models[0].id);
	await session.setModel('gpt-5-nano');
	const renewalsBeforeInference = renewalCount;
	const message = await session.sendAndWait({ prompt: 'Reply with exactly: native SDK fixture works' }, 60_000);
	assert.equal(message?.data.content, responseText);
	assert(renewalCount > renewalsBeforeInference, 'Inference must renew through the Agent Host bridge');
	const sessionId = session.sessionId;
	await session.disconnect();
	session = await client.resumeSession(sessionId, sessionOptions);
	await bridge.prepareSession(session, 'gpt-5-nano');
	assert.equal((await session.sendAndWait({ prompt: 'Reply with exactly: native SDK fixture works' }, 60_000))?.data.content, responseText);
	const posts = requests.filter(request => request.method === 'POST');
	assert.deepStrictEqual(posts.map(request => ({
		path: request.path, model: request.model, authorization: request.headers.authorization === `Bearer ${token}`,
		clientType: request.headers['x-clienttype'], scenario: request.headers['x-clientscenario'], feature: request.headers['x-clientfeature'],
	})), Array.from({ length: 2 }, () => ({ path: '/llmapi/chat/completions', model: 'gpt-5-nano', authorization: true, clientType: 'Copilot', scenario: 'Code', feature: 'LlmApiProxy' })));
	assert.equal(posts[0].headers['x-conversationid'], posts[1].headers['x-conversationid']);
	bridge.acceptToken({ ...initial, token: '' });
	await assert.rejects(session.sendAndWait({ prompt: 'This revoked turn must never reach inference.' }, 30_000), /token|credential|authentication|unavailable/i);
	assert.equal(requests.filter(request => request.method === 'POST').length, 2);
});

test('real Agent Host bridge + SDK + native runtime: catalog 500 preserves received correlation IDs', { timeout: 120_000 }, async t => {
	const requests = [];
	const responseRequestId = 'db67caed-2da5-4ca9-a35d-bf163fe82d5a';
	const server = createServer(async (request, response) => {
		for await (const _ of request) {
			// Consume the request before replying so the fixture mirrors a normal HTTP endpoint.
		}
		requests.push({ method: request.method, path: request.url, headers: request.headers });
		response.writeHead(500, {
			'Content-Type': 'application/json',
			'Request-Id': responseRequestId,
			'Set-Cookie': 'private-cookie',
		}).end('private response body must not reach diagnostics');
	});
	await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
	let home;
	let bridge;
	let client;
	t.after(async () => {
		try {
			await client?.stop();
		} finally {
			bridge?.dispose();
			server.closeAllConnections();
			await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
			if (home) {
				await rm(home, { recursive: true, force: true });
			}
		}
	});
	home = await mkdtemp(join(tmpdir(), 'agenthost-loki-sdk-correlation-fixture-'));
	const token = 'fake-host-owned-agenthost-fixture-token';
	const initial = { resource: NATIVE_LOKI_PROTECTED_RESOURCE.resource, scopes: [NATIVE_LOKI_SCOPE], token, _meta: nativeLokiAuthenticationMeta({ accountId: 'fixture-account' }) };
	bridge = new CopilotNativeLoki(resolve(process.env.VSCODE_NATIVE_LOKI_RUNTIME_ROOT ?? '.build/copilot-runtime-pr-22745/dist-cli'), undefined, resource => {
		bridge.acceptToken({ ...initial, _meta: resource._meta });
	}, new NullLogService());
	bridge.acceptToken(initial);
	client = new CopilotClient({
		...bridge.clientOptions,
		connection: RuntimeConnection.forStdio({ path: await bridge.resolveRuntimePath() }),
		useLoggedInUser: false,
		env: {
			PATH: process.env.PATH, HOME: home, COPILOT_HOME: home, TMPDIR: process.env.TMPDIR,
			COPILOT_DISABLE_KEYTAR: '1', COPILOT_CLI_TELEMETRY_OPTOUT: '1',
			COPILOT_LOKI_BASE_URL: `http://127.0.0.1:${server.address().port}/llmapi`,
		},
	});
	await client.start();
	const error = await bridge.listModels(client).then(
		() => assert.fail('the service failure must remain an RPC error'),
		error => error,
	);
	assert(typeof error === 'object' && error !== null && 'message' in error && typeof error.message === 'string');
	assert.deepStrictEqual(requests.map(request => ({ method: request.method, path: request.path })), [{ method: 'GET', path: '/llmapi/models' }]);
	const [request] = requests;
	const clientCallId = request.headers['x-clientcallid'];
	const conversationId = request.headers['x-conversationid'];
	assert.equal(typeof clientCallId, 'string');
	assert.equal(typeof conversationId, 'string');
	assert.match(clientCallId, /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
	assert.match(conversationId, /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
	assert.match(error.message, new RegExp(`HTTP 500.*X-ClientCallId=${clientCallId}.*X-ConversationId=${conversationId}.*response\\.request-id=${responseRequestId}`));
	assert.doesNotMatch(error.message, /private response body|private-cookie|fake-host-owned-agenthost-fixture-token/);
});

