test('real native runtime unions CAPI and Loki and retains each provider when the other is unavailable', { timeout: 120_000 }, async t => {
	const requests = [];
	let capiPickerEnabled = true;
	const server = createServer(async (request, response) => {
		let text = '';
		for await (const chunk of request) {
			text += chunk.toString();
		}
		requests.push({
			method: request.method, path: request.url, authorization: !!request.headers.authorization,
			integrationId: request.headers['copilot-integration-id'],
			model: request.method === 'POST' ? JSON.parse(text).model : undefined,
		});
		if (request.method === 'GET' && request.url === '/copilot_internal/user') {
			response.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({
				login: 'fixture-gh', endpoints: { api: `http://127.0.0.1:${server.address().port}` },
				copilotUser: { login: 'fixture-gh' },
			}));
		} else if (request.method === 'GET' && request.url === '/models') {
			response.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({
				data: [{
					id: 'fixture-shared', name: 'Fixture GitHub Copilot',
					capabilities: { type: 'chat', limits: { max_context_window_tokens: 128000, max_prompt_tokens: 110000, max_output_tokens: 16384 } },
					supported_endpoints: ['/chat/completions'],
					model_picker_enabled: capiPickerEnabled,
				}],
			}));
		} else if (request.method === 'GET' && request.url === '/llmapi/models') {
			response.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify({
				data: [{ id: 'fixture-shared', supported_endpoints: ['/chat/completions'] }],
			}));
		} else if (request.method === 'POST' && (request.url === '/llmapi/chat/completions' || request.url === '/chat/completions')) {
			const content = request.url.startsWith('/llmapi/') ? 'Loki fixture' : 'CAPI fixture';
			response.writeHead(200, { 'Content-Type': 'text/event-stream' }).end(
				`data: ${JSON.stringify({
					id: 'fixture', object: 'chat.completion.chunk', model: JSON.parse(text).model,
					choices: [{ index: 0, delta: { role: 'assistant', content }, finish_reason: 'stop' }],
					usage: { prompt_tokens: 1, completion_tokens: 2, total_tokens: 3 },
				})}\n\ndata: [DONE]\n\n`,
			);
		} else {
			response.writeHead(500).end('Unexpected local fixture request');
		}
	});
	server.on('connect', (request, socket) => {
		requests.push({ method: 'CONNECT', path: request.url, authorization: false });
		socket.end('HTTP/1.1 502 Bad Gateway\r\n\r\n');
	});
	await new Promise(respond => server.listen(0, '127.0.0.1', respond));
	let home;
	let bridge;
	let client;
	t.after(async () => {
		try {
			await client?.stop();
		} finally {
			bridge?.dispose();
			server.closeAllConnections();
			await new Promise((respond, reject) => server.close(error => error ? reject(error) : respond()));
			if (home) {
				await rm(home, { recursive: true, force: true });
			}
		}
	});
	home = await mkdtemp(join(tmpdir(), 'agenthost-dual-sdk-fixture-'));
	await writeFile(join(home, 'config.json'), '{"storeTokenPlaintext":true}\n', { mode: 0o600 });
	const accountId = 'fixture-account';
	const qualifiedLokiId = `@native/${Buffer.from(`loki:${accountId}`).toString('base64url')}/fixture-shared`;
	const initial = {
		resource: NATIVE_LOKI_PROTECTED_RESOURCE.resource,
		scopes: [NATIVE_LOKI_SCOPE],
		token: 'fixture-loki-token',
		_meta: nativeLokiAuthenticationMeta({ accountId }),
	};
	bridge = new CopilotNativeLoki(resolve(process.env.VSCODE_NATIVE_LOKI_RUNTIME_ROOT ?? '.build/copilot-runtime-dual-provider/dist-cli'), undefined, resource => {
		bridge.acceptToken({
			resource: resource.resource,
			scopes: resource.scopes_supported,
			token: isNativeEmuResource(resource.resource) ? '' : initial.token,
			_meta: resource._meta,
		});
	}, new NullLogService(), 30_000, accountId, true);
	bridge.acceptToken(initial);
	client = new CopilotClient({
		...bridge.clientOptions,
		connection: RuntimeConnection.forStdio({ path: await bridge.resolveRuntimePath() }),
		useLoggedInUser: false,
		env: {
			PATH: process.env.PATH, HOME: home, COPILOT_HOME: home, TMPDIR: process.env.TMPDIR,
			COPILOT_DISABLE_KEYTAR: '1', COPILOT_CLI_TELEMETRY_OPTOUT: '1',
			GITHUB_COPILOT_INTEGRATION_ID: 'copilot-developer-cli',
			COPILOT_DEBUG_GITHUB_API_URL: `http://127.0.0.1:${server.address().port}`,
			COPILOT_API_URL: `http://127.0.0.1:${server.address().port}`,
			COPILOT_LOKI_BASE_URL: `http://127.0.0.1:${server.address().port}/llmapi`,
			HTTP_PROXY: `http://127.0.0.1:${server.address().port}`,
			HTTPS_PROXY: `http://127.0.0.1:${server.address().port}`,
			NO_PROXY: '127.0.0.1,localhost',
		},
	});
	await client.start();
	const m365Only = await bridge.listModels(client);
	assert.deepStrictEqual(m365Only.map(model => [model.id, model.modelProviderId]), [[qualifiedLokiId, `loki:${accountId}`]]);
	const session = await client.createSession({
		availableTools: [], enableConfigDiscovery: false, infiniteSessions: { enabled: false }, streaming: true,
		disabledMcpServers: ['github-mcp-server'],
		onPermissionRequest: () => ({ kind: 'denied-interactively-by-user' }),
	});
	const events = [];
	const unsubscribe = session.on(event => {
		events.push({
			type: event.type,
			...(['session.error', 'session.warning'].includes(event.type) ? { message: event.data.message } : {}),
			...(['model.turn_ended', 'model.compaction_static_context_blocked'].includes(event.type)
				? { reason: event.data.reason, status: event.data.status, error: event.data.error } : {}),
			keys: Object.keys(event.data ?? {}),
		});
	});
	t.after(unsubscribe);
	await bridge.prepareSession(session, qualifiedLokiId);
	await session.rpc.accounts.set({
		command: { kind: 'setCredentials', host: 'https://github.com', login: 'fixture-gh', token: 'fixture-github-token' },
	});
	const both = await session.rpc.model.list({ skipCache: true, pickerFacing: false });
	const catalog = both.list.map(model => [model.id, model.modelProviderId]);
	assert.deepStrictEqual(catalog, [
		['auto', 'copilot'], ['fixture-shared', 'copilot'], [qualifiedLokiId, `loki:${accountId}`],
	]);
	const sendFixtureTurn = async (model, prompt) => {
		await session.setModel(model);
		try {
			return await session.sendAndWait({ prompt }, 60_000);
		} catch (error) {
			throw new Error(`${model} fixture failed after ${JSON.stringify(requests.map(({ method, path }) => ({ method, path })))}; events=${JSON.stringify(events.slice(-12))}: ${error instanceof Error ? error.message : String(error)}`);
		}
	};
	const capiReply = await sendFixtureTurn('fixture-shared', 'Say CAPI fixture');
	const lokiReply = await sendFixtureTurn(qualifiedLokiId, 'Say Loki fixture');
	bridge.acceptToken({ ...initial, token: '' });
	const capiOnly = await session.rpc.model.list({ skipCache: true, pickerFacing: false });
	await assert.rejects(sendFixtureTurn(qualifiedLokiId, 'Do not fall back to CAPI'));
	capiPickerEnabled = false;
	bridge.acceptToken(initial);
	const m365OnlyAfterNoCapi = await session.rpc.model.list({ skipCache: true, pickerFacing: false });
	assert.deepStrictEqual({
		capiReply: capiReply?.data.content,
		lokiReply: lokiReply?.data.content,
		capiOnly: capiOnly.list.map(model => [model.id, model.modelProviderId]),
		m365OnlyAfterNoCapi: m365OnlyAfterNoCapi.list.map(model => [model.id, model.modelProviderId]),
		networkPaths: [...new Set(requests.map(({ method, path }) => `${method} ${path}`))].sort(),
		upstreamModelIds: requests.filter(request => request.method === 'POST').map(request => [request.path, request.model]),
		modelRequestsAuthenticated: requests.filter(request => request.path === '/models' || request.path === '/llmapi/models'
			|| request.path === '/chat/completions' || request.path === '/llmapi/chat/completions')
			.every(request => request.authorization),
		capiIntegrationIds: [...new Set(requests.filter(request => request.path === '/models' || request.path === '/chat/completions')
			.map(request => `${request.method} ${request.path} ${request.integrationId}`))].sort(),
	}, {
		capiReply: 'CAPI fixture',
		lokiReply: 'Loki fixture',
		capiOnly: [['auto', 'copilot'], ['fixture-shared', 'copilot']],
		m365OnlyAfterNoCapi: [[qualifiedLokiId, `loki:${accountId}`]],
		networkPaths: ['GET /copilot_internal/user', 'GET /llmapi/models', 'GET /models', 'POST /chat/completions', 'POST /llmapi/chat/completions'],
		upstreamModelIds: [['/chat/completions', 'fixture-shared'], ['/llmapi/chat/completions', 'fixture-shared']],
		modelRequestsAuthenticated: true,
		capiIntegrationIds: ['GET /models copilot-developer-cli', 'POST /chat/completions copilot-developer-cli'],
	});
});

