async function fileHash(path) {
	const hash = createHash('sha256');
	for await (const bytes of createReadStream(path)) {
		hash.update(bytes);
	}
	return hash.digest('hex');
}

async function countPersistedBearers(directory, tokens) {
	let matches = 0;
	for (const entry of await readdir(directory, { withFileTypes: true })) {
		const path = join(directory, entry.name);
		if (entry.isDirectory()) {
			matches += await countPersistedBearers(path, tokens);
		} else if (entry.isFile()) {
			const contents = await readFile(path);
			matches += [...tokens].filter(token => contents.includes(Buffer.from(token))).length;
		}
	}
	return matches;
}

async function waitFor(operation, message, signal, timeout) {
	let timer;
	let onAbort;
	try {
		signal?.throwIfAborted();
		return await Promise.race([
			operation,
			new Promise((_, reject) => timer = setTimeout(() => reject(new Error(message)), timeout)),
			new Promise((_, reject) => {
				onAbort = () => reject(new Error('Native RPC probe cancelled'));
				signal?.addEventListener('abort', onAbort, { once: true });
			}),
		]);
	} finally {
		clearTimeout(timer);
		signal?.removeEventListener('abort', onAbort);
	}
}

async function createTunnelObserver(endpoint, currentStage, requests) {
	const sockets = new Set();
	const allowed = new URL(endpoint);
	const server = createServer((_request, response) => response.writeHead(405).end());
	server.on('connect', (request, downstream, head) => {
		const target = new URL(`https://${request.url}`);
		const port = Number(target.port || 443);
		const blocked = target.hostname !== allowed.hostname || port !== Number(allowed.port || 443);
		requests.push({ stage: currentStage(), host: target.hostname, port, blocked });
		if (blocked) {
			downstream.end('HTTP/1.1 403 Forbidden\r\nConnection: close\r\n\r\n');
			return;
		}
		const upstream = connectSocket({ host: target.hostname, port });
		for (const socket of [downstream, upstream]) {
			sockets.add(socket);
			socket.once('close', () => sockets.delete(socket));
		}
		upstream.once('connect', () => {
			downstream.write('HTTP/1.1 200 Connection Established\r\n\r\n');
			if (head.length) {
				upstream.write(head);
			}
			upstream.pipe(downstream);
			downstream.pipe(upstream);
		});
		upstream.on('error', () => downstream.destroy());
		downstream.on('error', () => upstream.destroy());
		downstream.on('close', () => upstream.destroy());
		upstream.on('close', () => downstream.destroy());
	});
	await new Promise((resolve, reject) => {
		server.once('error', reject);
		server.listen(0, '127.0.0.1', () => {
			server.off('error', reject);
			resolve();
		});
	});
	const address = server.address();
	assert(address && typeof address !== 'string');
	return {
		url: `http://127.0.0.1:${address.port}`,
		async close() {
			for (const socket of sockets) {
				socket.destroy();
			}
			await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
		},
	};
}

export async function runNativeLokiRpc({ acquireToken, signal, endpoint, onProgress = () => {}, observeNetwork = true }) {
