	const runtimePath = join(root, 'prebuilds/darwin-arm64/copilot-runtime');
	const tokens = new Set();
	const tokenRequests = [];
	const network = [];
	let stage = 'startup';
	const result = {
		kind: 'nativeLokiInference',
		ok: false,
		transport: 'raw-stdio-jsonrpc',
		typedSdkClientUsed: false,
		customProviderConfigured: false,
		customRequestHandlerInstalled: false,
		githubCredentialConfigured: false,
		runtimeCommit: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
		runtimeHasLocalAuthPatch: Boolean(execFileSync('git', ['diff', '--name-only', 'HEAD', '--'], { cwd: root, encoding: 'utf8' }).trim()),
		runtimeSha256: await fileHash(runtimePath),
		runtimeAddonSha256: await fileHash(join(root, 'prebuilds/darwin-arm64/runtime.node')),
		endpoint: endpoint ?? lokiEndpoint,
		scope: lokiScope,
		tokenRequests,
		network,
	};
	const home = await mkdtemp(join(tmpdir(), 'vscode-native-loki-rpc-'));
	const redact = text => {
		let value = String(text);
		for (const token of tokens) {
			value = value.replaceAll(token, '[redacted]');
		}
		return value.replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, '[redacted-jwt]');
	};
	const setStage = value => {
		stage = value;
		onProgress(value);
	};
	let tunnel;
	let child;
	let exited;
	let connection;
	let sessionId;
	let stderr = '';
	const acquisitions = new Map();
	const cancelAcquisitions = () => {
		for (const controller of acquisitions.values()) {
			controller.abort();
		}
	};
	signal?.addEventListener('abort', cancelAcquisitions);
	const request = async (method, params = {}, timeout = 90_000) => {
		signal?.throwIfAborted();
		return waitFor(connection.sendRequest(method, params), `${method} timed out`, signal, timeout);
	};
	try {
		signal?.throwIfAborted();
		if (observeNetwork) {
			tunnel = await createTunnelObserver(endpoint ?? lokiEndpoint, () => stage, network);
		}
		child = spawn(runtimePath, ['--headless', '--no-auto-update', '--stdio', '--no-auto-login', '--log-level', 'error'], {
			cwd: home,
			env: {
				PATH: process.env.PATH,
				HOME: home,
				COPILOT_HOME: home,
				COPILOT_DISABLE_KEYTAR: '1',
				COPILOT_CLI_TELEMETRY_OPTOUT: '1',
				TMPDIR: process.env.TMPDIR,
				...(endpoint ? { COPILOT_LOKI_BASE_URL: endpoint } : {}),
				...(tunnel ? { HTTPS_PROXY: tunnel.url, HTTP_PROXY: tunnel.url, NO_PROXY: '' } : {}),
			},
			stdio: ['pipe', 'pipe', 'pipe'],
		});
		exited = new Promise((resolve, reject) => {
			child.once('exit', resolve);
			child.once('error', reject);
		});
		exited.catch(() => {});
		child.stderr.on('data', bytes => stderr = (stderr + bytes.toString()).slice(-12_000));
		connection = createMessageConnection(new StreamMessageReader(child.stdout), new StreamMessageWriter(child.stdin));
		connection.onClose(() => {
			cancelAcquisitions();
			connection.dispose();
		});
		connection.onRequest('accountToken.getToken', async params => {
			const controller = new AbortController();
			assert(!acquisitions.has(params.requestId), 'Duplicate token acquisition');
			acquisitions.set(params.requestId, controller);
			const { requestId, ...tokenRequest } = params;
			tokenRequests.push({
				stage,
				reason: tokenRequest.reason,
				scopes: tokenRequest.scopes,
				audience: tokenRequest.audience,
				accountBound: Boolean(tokenRequest.accountId),
			});
			try {
				const acquired = await acquireToken(tokenRequest, controller.signal);
				if (controller.signal.aborted || signal?.aborted) {
					return { kind: 'unavailable' };
				}
				if (acquired.kind === 'ok') {
					assert(acquired.accessToken, 'Host returned an empty token');
					tokens.add(acquired.accessToken);
				}
				return acquired;
			} finally {
				acquisitions.delete(requestId);
			}
		});
		connection.onNotification('accountToken.cancel', params => acquisitions.get(params.requestId)?.abort());
		let response = '';
		let streamedChunks = 0;
		let finish;
		let fail;
		const completed = new Promise((resolve, reject) => {
			finish = resolve;
			fail = reject;
		});
		// Attach a rejection observer before a failure notification can arrive.
		completed.catch(() => {});
		connection.onNotification('session.event', notification => {
			if (notification.sessionId !== sessionId || stage !== 'inference') {
				return;
			}
			const event = notification.event;
			if (event?.type === 'assistant.message_delta') {
				streamedChunks++;
			} else if (event?.type === 'assistant.message' && typeof event.data?.content === 'string') {
				response = event.data.content;
			} else if (event?.type === 'session.error') {
				fail(new Error(event.data?.message || 'Native runtime turn failed'));
			} else if (event?.type === 'session.idle' && response.trim()) {
				finish();
			}
		});
		connection.listen();
		const handshake = await request('connect', { supportsHostTokenSource: true, supportedTaskKinds: ['agent', 'shell'] });
		assert.equal(handshake.hostTokenSourceRegistered, true);
		result.protocolVersion = handshake.protocolVersion;
		const session = await request('session.create', {
			sessionId: randomUUID(),
			workingDirectory: home,
			configDir: home,
			enableConfigDiscovery: false,
			availableTools: [],
			infiniteSessions: { enabled: false },
			streaming: true,
		});
		sessionId = session.sessionId;
		setStage('host-sign-in');
		const flow = await request('session.accounts.login.begin', { sessionId, kind: 'entra' });
		let step = flow.step;
		while (step.kind === 'needs-interaction' || step.kind === 'awaiting') {
			step = await request('session.accounts.login.advance', { sessionId, flowId: flow.flowId });
		}
		assert.equal(step.kind, 'completed', step.message || 'Host sign-in did not complete');
		assert.equal(step.result?.status, 'completed', 'Host declined sign-in');
		const accounts = await request('session.accounts.enumerate', { sessionId, query: { kind: 'accounts' } });
		result.accountKinds = [...new Set(accounts.items.map(account => account.kind))];
		assert(result.accountKinds.includes('entra') && result.accountKinds.includes('loki'), 'Native account derivation is incomplete');
		assert(result.accountKinds.every(kind => kind === 'entra' || kind === 'loki'), 'Unexpected GitHub/EMU account');
		setStage('native-catalog');
		const catalog = await request('session.model.list', { sessionId, skipCache: true, pickerFacing: false });
		const models = catalog.list.filter(model => model.modelProviderId === 'loki');
		result.nativeModels = models.map(model => ({ id: model.id, name: model.name, provider: model.modelProviderId }));
		assert(models.length, 'Native Loki catalog returned no models');
		const model = models.find(model => model.id.includes('gpt-5-mini')) ?? models[0];
		result.model = model.id;
		await request('session.models.set', { sessionId, command: { kind: 'select', modelId: model.id } });
		const selected = await request('session.models.get', { sessionId, query: { kind: 'current' } });
		assert.equal(selected.selection?.modelId, model.id);
		setStage('inference');
		const prompt = 'Reply with exactly: native Loki RPC works';
		await request('session.send', { sessionId, prompt, mode: 'immediate' });
		await waitFor(completed, 'Native Loki turn timed out', signal, 90_000);
		if (tunnel) {
			const destination = new URL(endpoint ?? lokiEndpoint).hostname;
			assert(network.some(entry => entry.host === destination), 'Runtime did not use the observed Loki connection');
			assert(network.every(entry => !entry.blocked), 'Runtime attempted an unexpected destination');
			assert(network.filter(entry => entry.stage === 'inference').every(entry => entry.host === destination), 'Unexpected inference destination');
		}
		assert(tokenRequests.some(entry => entry.stage === 'inference' && entry.reason === 'renewal' && entry.accountBound
			&& entry.scopes.length === 1 && entry.scopes[0] === lokiScope), 'No account-bound Loki token acquisition for inference');
		result.response = response;
		result.streamedChunks = streamedChunks;
		result.ok = true;
	} catch (error) {
		result.stage = stage;
		result.code = String(error.code ?? error.name ?? 'Error');
		result.details = redact(error.message).slice(0, 4000);
		result.stderr = redact(stderr).slice(-4000);
	} finally {
		signal?.removeEventListener('abort', cancelAcquisitions);
		cancelAcquisitions();
		if (connection && sessionId && !signal?.aborted) {
			try {
				await request('session.destroy', { sessionId }, 10_000);
			} catch (error) {
				result.cleanupError = redact(error.message);
				result.ok = false;
			}
		}
		connection?.dispose();
		if (child) {
			child.kill('SIGTERM');
			const timer = setTimeout(() => child.kill('SIGKILL'), 5000);
			try {
				await exited;
			} finally {
				clearTimeout(timer);
			}
			result.runtimeExitCode = child.exitCode;
			result.runtimeExitSignal = child.signalCode;
		}
		if (tunnel) {
			await tunnel.close();
		}
		try {
			result.persistedBearerCount = await countPersistedBearers(home, tokens);
			if (result.persistedBearerCount !== 0) {
				result.ok = false;
				result.stage = 'credential-persistence';
				result.code = 'UnexpectedPersistedBearer';
			}
		} finally {
			await rm(home, { recursive: true });
		}
		result.cleanupComplete = true;
	}
	return JSON.parse(redact(JSON.stringify(result)));
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
	assert(process.send, 'Run this probe through its private IPC parent');
	const controller = new AbortController();
	const pending = new Map();
	const send = (message, afterSend) => {
		if (process.connected) {
			process.send(message, error => {
				if (error) {
					controller.abort();
				}
				afterSend?.();
			});
		}
	};
	const disconnect = () => {
		if (process.connected) {
			process.disconnect();
		}
	};
	process.once('SIGTERM', () => controller.abort());
	process.once('disconnect', () => controller.abort());
	process.on('message', message => {
		if (message.type === 'tokenResult') {
			const request = pending.get(message.id);
			if (request) {
				pending.delete(message.id);
				message.error ? request.reject(new Error(message.error)) : request.resolve(message.result);
			}
		} else if (message.type === 'cancel') {
			controller.abort();
		}
	});
	process.once('message', async message => {
		assert.equal(message.type, 'start');
		try {
			const result = await runNativeLokiRpc({
				signal: controller.signal,
				onProgress: stage => send({ type: 'progress', stage }),
				acquireToken: (request, signal) => new Promise((resolve, reject) => {
					const id = randomUUID();
					const onAbort = () => {
						signal.removeEventListener('abort', onAbort);
						pending.delete(id);
						send({ type: 'tokenCancel', id });
						resolve({ kind: 'unavailable' });
					};
					signal.addEventListener('abort', onAbort, { once: true });
					pending.set(id, {
						resolve: value => {
							signal.removeEventListener('abort', onAbort);
							resolve(value);
						},
						reject: error => {
							signal.removeEventListener('abort', onAbort);
							reject(error);
						},
					});
					send({ type: 'tokenRequest', id, request });
				}),
			});
			send({ type: 'result', result }, disconnect);
		} catch (error) {
			send({
				type: 'failure',
				message: `Native RPC probe setup or cleanup failed: ${String(error.message).replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, '[redacted-jwt]')}`,
			}, disconnect);
			process.exitCode = 1;
		}
	});
}

