import assert from 'node:assert/strict';

export function parseLokiCatalog(body) {
	assert(Array.isArray(body?.data), 'Loki catalog did not contain a data array');
	return body.data.filter(model => typeof model?.id === 'string' && model.id.length > 0).map(model => ({
		id: model.id,
		supportedEndpoints: Array.isArray(model.supported_endpoints)
			? model.supported_endpoints.filter(endpoint => typeof endpoint === 'string')
			: [],
	}));
}

function protocolFor(model) {
	if (model.supportedEndpoints.includes('/v1/messages')) {
		return { type: 'anthropic', endpoint: '/v1/messages' };
	}
	if (model.supportedEndpoints.includes('/responses')) {
		return { type: 'openai', wireApi: 'responses', endpoint: '/responses' };
	}
	if (model.supportedEndpoints.includes('/chat/completions')) {
		return { type: 'openai', wireApi: 'completions', endpoint: '/chat/completions' };
	}
	return undefined;
}

export function selectLokiModel(models, requestedId) {
	const selected = requestedId === undefined
		? models.find(model => model.id === 'gpt-5-mini' && protocolFor(model)) ?? models.find(model => protocolFor(model))
		: models.find(model => model.id === requestedId);
	assert(selected, requestedId ? `Requested model ${requestedId} was not in the Loki catalog` : 'Loki advertised no supported inference models');
	const protocol = protocolFor(selected);
	assert(protocol, `Loki did not advertise a supported inference endpoint for ${selected.id}`);
	return { ...selected, ...protocol };
}

