/** One instance per runtime conversation; all requests within a turn share its call ID. */
export class LokiHeaders {
	#conversationId = randomUUID();
	#clientCallId;

	get conversationId() {
		return this.#conversationId;
	}

	beginTurn() {
		this.#clientCallId = randomUUID();
	}

