			headers.set(name, value);
		}
		headers.set('X-ConversationId', this.#conversationId);
		if (this.#clientCallId) {
			headers.set('X-ClientCallId', this.#clientCallId);
		} else {
			headers.delete('X-ClientCallId');
		}
		return new Request(request, { headers, redirect: 'error' });
	}
}

