import { test } from 'node:test';
import { LokiHeaders } from './loki-headers.mjs';

const guid = /^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;

function newRequest() {
	return new Request('https://df.loki.delve.office.com/api/v1/llmapi/chat/completions', {
		method: 'POST',
		headers: { authorization: 'Bearer fake-token', 'content-type': 'application/json' },
		body: JSON.stringify({ model: 'test-model', messages: [{ role: 'user', content: '19 + 23?' }] }),
	});
}

test('conversation ID is a GUID; the optional call ID is absent before a turn', () => {
	const correlation = new LokiHeaders();
	const request = correlation.applyTo(newRequest());
	assert.match(request.headers.get('X-ConversationId'), guid);
	assert.deepStrictEqual({
		conversation: request.headers.get('X-ConversationId'),
		call: request.headers.get('X-ClientCallId'),
		clientType: request.headers.get('X-ClientType'),
		clientScenario: request.headers.get('X-ClientScenario'),
		clientFeature: request.headers.get('X-ClientFeature'),
	}, { conversation: correlation.conversationId, call: null, clientType: 'Copilot', clientScenario: 'Code', clientFeature: 'LlmApiProxy' });
});

test('retries keep both IDs, later turns change only the call ID, and conversations are distinct', () => {
	const correlation = new LokiHeaders();
	const snapshot = owner => {
		const request = owner.applyTo(newRequest());
		return {
			conversation: request.headers.get('X-ConversationId'),
			call: request.headers.get('X-ClientCallId'),
		};
	};
	correlation.beginTurn();
	const first = snapshot(correlation);
	const retry = snapshot(correlation);
	correlation.beginTurn();
	const next = snapshot(correlation);
	const otherConversation = new LokiHeaders();
	otherConversation.beginTurn();
	const other = snapshot(otherConversation);

	assert.deepStrictEqual({
		allGuids: [first, retry, next, other].every(ids => guid.test(ids.conversation) && guid.test(ids.call)),
		retryMatches: first.conversation === retry.conversation && first.call === retry.call,
		conversationStable: first.conversation === next.conversation,
		turnChanged: first.call !== next.call,
		conversationsDistinct: first.conversation !== other.conversation,
	}, { allGuids: true, retryMatches: true, conversationStable: true, turnChanged: true, conversationsDistinct: true });
});

test('header injection preserves the runtime body and credential and forbids redirects', async () => {
	const correlation = new LokiHeaders();
	correlation.beginTurn();
	const original = newRequest();
	const body = await original.clone().text();
	const outgoing = correlation.applyTo(original);
	assert.deepStrictEqual({
		body: await outgoing.text(),
		credential: outgoing.headers.get('authorization'),
		contentType: outgoing.headers.get('content-type'),
		redirect: outgoing.redirect,
	}, { body, credential: 'Bearer fake-token', contentType: 'application/json', redirect: 'error' });
});

